import itertools
import json

def compute_itinerary():
    # Input variables (constraints)
    total_days = 12
    cities = ["Prague", "Berlin", "Tallinn", "Stockholm"]
    required_days = {
        "Prague": 2,
        "Berlin": 3,
        "Tallinn": 5,
        "Stockholm": 5
    }
    # Direct flights (undirected)
    direct_pairs = {
        frozenset(("Berlin", "Tallinn")),
        frozenset(("Prague", "Tallinn")),
        frozenset(("Stockholm", "Tallinn")),
        frozenset(("Prague", "Stockholm")),
        frozenset(("Stockholm", "Berlin")),
    }
    def has_direct(a, b):
        return frozenset((a, b)) in direct_pairs

    # Day-specific constraints
    conference_in_berlin_days = {6, 8}
    tallinn_relatives_days = set(range(8, 13))  # 8..12 inclusive

    # Helper: build segment schedule for a permutation using overlap logic
    def build_segments(order):
        # Overlap model: segment i is [start_i, end_i] inclusive
        # start_1 = 1; for each i>1: start_i = end_{i-1} (flight day counts for both)
        segments = []
        start = 1
        for c in order:
            end = start + required_days[c] - 1
            segments.append((c, start, end))
            start = end  # next segment overlaps on this day (flight day)
        return segments

    # Validate a schedule against all constraints
    def is_feasible(segments):
        # 1) Ends on total_days
        if segments[-1][2] != total_days:
            return False

        # 2) All consecutive cities have direct flights
        for i in range(len(segments) - 1):
            a = segments[i][0]
            b = segments[i + 1][0]
            if not has_direct(a, b):
                return False

        # 3) Per-city lengths match required (implied by build, but verify)
        for c, s, e in segments:
            if (e - s + 1) != required_days[c]:
                return False

        # 4) Presence constraints
        city_ranges = {c: (s, e) for c, s, e in segments}

        # Berlin conference days must be within Berlin's range
        b_s, b_e = city_ranges["Berlin"]
        for d in conference_in_berlin_days:
            if not (b_s <= d <= b_e):
                return False

        # Tallinn relatives days must be within Tallinn's range
        t_s, t_e = city_ranges["Tallinn"]
        for d in tallinn_relatives_days:
            if not (t_s <= d <= t_e):
                return False

        return True

    # Search over permutations to compute a feasible itinerary
    feasible = None
    for order in itertools.permutations(cities):
        # Quick prune: last city must be Tallinn for relatives window (since it's exactly 5 days 8..12)
        if order[-1] != "Tallinn":
            continue
        segments = build_segments(order)
        if is_feasible(segments):
            feasible = segments
            break

    if not feasible:
        raise RuntimeError("No feasible itinerary found under given constraints.")

    # Build JSON output: list of day_range/place mappings
    itinerary = []
    for c, s, e in feasible:
        itinerary.append({"day_range": f"Day {s}-{e}", "place": c})

    return {"itinerary": itinerary}

if __name__ == "__main__":
    result = compute_itinerary()
    print(json.dumps(result, ensure_ascii=False))
